def clamp(n: int, low: int, high: int) -> int:
    return min(max(n, low), high)

# SPDX-License-Identifier: GPL-3.0-or-later
# Copyright (c) 2026 Ada Example
def absolute(n: int) -> int:
    if n < 0:
        return -n
    return n
